/* * tstring.h * * 88-10-01 v1.0	created by greg yachuk, placed in the public domain * 88-10-06 v1.1	changed prerequisite list handling * */#define	tnew(t)		((t *) talloc(sizeof(t)))#define	tfree(t)	(free((char *) t))#define	tstrcat(s,p)	(strcat(strcpy(talloc(strlen(s)+strlen(p)+1),(s)),(p)))#define	tstrcpy(s)	(strcpy(talloc(strlen(s)+1), (s)))#ifdef	MSDOSchar   *talloc(int n);char   *trealloc(char *s, int n);char   *tstrncpy(char *s, int n);int	terror(int n, char *s);char   *token(char *s, char *sep);char  **tokenize(char *input);char   *tgets(FILE *fd);#elsechar   *talloc();char   *trealloc();char   *tstrncpy();int	terror();char   *token();char  **tokenize();char   *tgets();#endif